#include <math.h>
#ifndef _MSC_VER
#define __forceinline inline
#endif

unsigned long g_InvSqrtMantissaTable[128];          // 0x013CE558 (filled in main)

struct C3DVector {
    float X, Y, Z;
    C3DVector() {}
    C3DVector(float x, float y, float z) : X(x), Y(y), Z(z) {}
