    // 1/sqrt(x) scaled so that the exponent (0x17c - e) >> 1 is right (x in [1,4) -> estimate = 0.5 * (1 + mantissa)).
    for (int i = 0; i < 128; ++i) {
        double m = 1.0 + ((i & 63) + 0.5) / 64.0;
        double x = m * ((i >> 6) ? 1.0 : 2.0);     // bit 6 set = odd exponent (x in [1,2)), clear = even (x in [2,4))
        double r = 1.0 / sqrt(x);
